The bug: `Interval.fromISO` with `Settings.throwOnInvalid` — when parsing fails, `Interval.invalid` throws InvalidIntervalError. But the issue: `DateTime.fromISO(s, opts)` with throwOnInvalid throws immediately for invalid date. Hmm, but the test "Interval.fromISO works with Settings.throwOnInvalid" — expected behavior likely: throws InvalidIntervalError (not InvalidArgumentError or something else).

Let's look at the actual upstream fix. In luxon, the fix was:

```js
  static fromISO(text, opts) {
    const [s, e] = (text || "").split("/", 2);
    if (s && e) {
      let start, startIsValid;
      try {
        start = DateTime.fromISO(s, opts);
        startIsValid = start.isValid;
      } catch (e) {
        startIsValid = false;
      }

      let end, endIsValid;
      try {
        end = DateTime.fromISO(e, opts);
        endIsValid = end.isValid;
      } catch (e) {
        endIsValid = false;
      }

      if (startIsValid && endIsValid) {
        return Interval.fromDateTimes(start, end);
      }

      if (startIsValid) {
        const dur = Duration.fromISO(e, opts);
        if (dur.isValid) {
          return Interval.after(start, dur);
        }
      } else if (endIsValid) {
        const dur = Duration.fromISO(s, opts);
        if (dur.isValid) {
          return Interval.before(end, dur);
        }
      }
    }
    return Interval.invalid("unparsable", `the input "${text}" can't be parsed as ISO 8601`);
  }
```

